class Widget {};
void processWidget(std::shared_ptr<Widget> spw, int priority) {}
int computePriority() { throw std::runtime_error("Error!"); return 0; }

void runExample() {
    // Problematic case: potential leak with direct new
    try {
        // Evaluation order is unspecified. If new Widget executes, then computePriority throws,
        // the memory for Widget is leaked because the shared_ptr constructor is never called.
        processWidget(std::shared_ptr<Widget>(new Widget()), computePriority());
    } catch (...) {
        // A leak may have occurred.
    }

    // Preferred modern C++ approach: exception-safe and efficient
    // The make_shared call is a single operation; no interleaving is possible.
    auto spw = std::make_shared<Widget>();
    try {
        processWidget(spw, computePriority());
    } catch (...) {
        // No leak. spw manages the Widget's lifetime.
    }

    // Unique pointer creation
    auto upw = std::make_unique<Widget>(); // The default, safe way
}
